const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Kyiv geometry (city center and surrounding area)
  const kyiv = ee.Geometry.Point([30.5234, 50.4501]).buffer(10000); // 10km radius

  // 2. Load VIIRS Nighttime Lights data
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

  // January 2022
  const jan2022 = viirs
    .filterDate('2022-01-01', '2022-01-31')
    .filterBounds(kyiv);

  // March 2022
  const mar2022 = viirs
    .filterDate('2022-03-01', '2022-03-31')
    .filterBounds(kyiv);

  // 3. Check collection sizes
  const janSize = jan2022.size().getInfo();
  const marSize = mar2022.size().getInfo();

  console.log('January 2022 Images:', janSize);
  console.log('March 2022 Images:', marSize);

  if (janSize === 0 || marSize === 0) {
    console.log('Missing data for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get mean composites
  const janImage = jan2022.select('avg_rad').mean();
  const marImage = mar2022.select('avg_rad').mean();

  // 5. Calculate statistics with pixel count validation
  const janStats = janImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: kyiv,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const marStats = marImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: kyiv,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const janMean = janStats['avg_rad_mean'];
  const janCount = janStats['avg_rad_count'];
  const marMean = marStats['avg_rad_mean'];
  const marCount = marStats['avg_rad_count'];

  console.log('January 2022 - Mean:', janMean, 'Pixels:', janCount);
  console.log('March 2022 - Mean:', marMean, 'Pixels:', marCount);

  // 6. Validate pixel counts
  if (janCount === 0 || marCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Validate calculation results
  if (janMean === null || janMean === undefined || marMean === null || marMean === undefined) {
    console.log('Calculation returned null/undefined.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(janMean) || isNaN(marMean)) {
    console.log('Calculation returned NaN.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and determine answer
  const percentChange = ((marMean - janMean) / janMean * 100).toFixed(2);
  console.log('Change:', percentChange + '%');

  if (marMean < janMean) {
    console.log('March nighttime lights decreased compared to January.');
    console.log('<answer>A</answer>');
  } else {
    console.log('March nighttime lights did not decrease compared to January.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
